INSERT INTO engage.chat_message (id, thread_id, sender_user_id, body_enc, enc_key_id, sent_at) VALUES
  ('cfd00000-0220-4000-8000-000000000011', 'cfd00000-0218-4000-8000-000000000002', 'cfd00000-0002-4000-8000-000000001003', convert_to('Lab says my HbA1c sample is taken. When will you see the result?', 'UTF8'), 'demo-none', '2026-10-17 11:40:00+05:30'),
  ('cfd00000-0220-4000-8000-000000000012', 'cfd00000-0218-4000-8000-000000000003', 'cfd00000-0002-4000-8000-000000001011', convert_to('Fever is less today, 99 F. Still tired.', 'UTF8'), 'demo-none', '2026-10-17 09:05:00+05:30'),
  ('cfd00000-0220-4000-8000-000000000013', 'cfd00000-0218-4000-8000-000000000003', 'cfd00000-0002-4000-8000-000000000002', convert_to('Good. Keep drinking fluids. The dengue test result will come by evening, I will message you.', 'UTF8'), 'demo-none', '2026-10-17 09:20:00+05:30'),
  ('cfd00000-0220-4000-8000-000000000014', 'cfd00000-0218-4000-8000-000000000004', 'cfd00000-0002-4000-8000-000000001006', convert_to('BP at home 138/88 this week.', 'UTF8'), 'demo-none', '2026-10-15 09:10:00+05:30'),
  ('cfd00000-0220-4000-8000-000000000015', 'cfd00000-0218-4000-8000-000000000004', 'cfd00000-0002-4000-8000-000000000002', convert_to('Thank you. Continue amlodipine; we will review on Tuesday.', 'UTF8'), 'demo-none', '2026-10-15 11:25:00+05:30'),
  ('cfd00000-0220-4000-8000-000000000016', 'cfd00000-0218-4000-8000-000000000005', 'cfd00000-0002-4000-8000-000000001007', convert_to('Is it safe to take paracetamol for headache?', 'UTF8'), 'demo-none', '2026-10-14 10:40:00+05:30'),
  ('cfd00000-0220-4000-8000-000000000017', 'cfd00000-0218-4000-8000-000000000005', 'cfd00000-0002-4000-8000-000000000002', convert_to('Yes, paracetamol 500 mg up to 3 times a day is fine. Tell us if headaches persist.', 'UTF8'), 'demo-none', '2026-10-14 11:25:00+05:30')
